#!/usr/bin/env bash
# recipes/crate-android-system-properties--0-1-5/build.sh -- stage the android_system_properties 0.1.5 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/android_system_properties-0.1.5"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"819e7219dbd41043ac279b19830f2efc897156490d7fd6ea916720117ee66311"}\n' > "${dest}/.cargo-checksum.json"
